sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float speed;
uniform float intensity;
uniform float seed;
uniform float style;
uniform float wave;
float hash21(float2 p)
{
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
float3 permute3(float3 x)
{
    return mod((x * 34.0 + 1.0) * x, 289.0);
}
float snoise2(float2 v)
{
    float4 C = float4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
    float2 i = floor(v + dot(v, C.yy));
    float2 x0 = v - i + dot(i, C.xx);
    float2 i1 = x0.x > x0.y ? float2(1.0, 0.0) : float2(0.0, 1.0);
    float4 x12 = x0.xyxy + C.xxzz;
    x12.xy -= i1;
    i = mod(i, 289.0);
    float3 p = permute3(permute3(i.y + float3(0.0, i1.y, 1.0)) + i.x + float3(0.0, i1.x, 1.0));
    float3 m = max(0.5 - float3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
    m = m * m;
    m = m * m;
    float3 x = 2.0 * fract(p * C.www) - 1.0;
    float3 h = abs(x) - 0.5;
    float3 a0 = x - floor(x + 0.5);
    m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);
    float3 g = float3(a0.x * x0.x + h.x * x0.y, a0.yz * x12.xz + h.yz * x12.yw);
    return 130.0 * dot(m, g);
}
half4 main(float2 coord)
{
    half4 c = image.eval(coord);
    if (c.a <= 0.001 || speed <= 0.0 || intensity <= 0.0) return c;
    if (wave > 0.5) {
        float n = 0.593 + 0.243 * snoise2(float2(time * speed * 0.7, seed * 7.13 + 1.7));
        return c * half(pow(clamp(1.0 - intensity * n, 0.0, 1.0), 2.55));
    }
    float f = time * speed;
    float n = floor(f);
    float ramp = 0.15;
    float t = clamp((f - n - (1.0 - ramp)) / ramp, 0.0, 1.0);
    float r = mix(hash21(float2(mod(n, 4096.0), seed)), hash21(float2(mod(n + 1.0, 4096.0), seed)), t);
    float keep = clamp(1.0 - intensity * (style > 0.5 ? 0.5 + 0.3 * r : r), 0.0, 1.0);
    return c * half(style > 0.5 ? keep * keep : keep);
}
